1	"use server";
2	
3	/**
4	 * Control panel — One-click apps.
5	 *
6	 * Install WordPress / Nextcloud / … onto the server: provision a site (vhost +
7	 * docroot) + a database + the app, then report the URL / credentials. This
8	 * reuses the Website + VpsDatabase primitives — installApp creates all three
9	 * rows (AppInstall, Website, VpsDatabase) and enqueues one APP_INSTALL job;
10	 * worker/apps.ts drives the whole install over SSH (sandbox-simulated on
11	 * staging). Generated passwords are shown once (returned here).
12	 *
13	 * HOW MUCH we install differs per app and is declared once, in `APP_MODES`
14	 * (worker/apps.ts) — imported here so the promise, the credentials handed over
15	 * and the installer can never drift apart:
16	 *
17	 *   managed  → the worker completes first-run setup, so an admin password is
18	 *              generated and stored encrypted for the worker to apply.
19	 *   assisted → the application creates its own admin account in its own setup
20	 *              wizard, so we DO NOT generate an "admin password" for it. Handing
21	 *              over a password that opens nothing is exactly the bug QA found
22	 *              (P1-22): `adminPassEnc` was written, shown as "save this now",
23	 *              and never used by anything.
24	 *   unavailable → refused here, with the reason, instead of being sold.
25	 */
26	import { revalidatePath } from "next/cache";
27	import { db } from "./db";
28	import { requireUser } from "./auth";
29	import { checkRateLimit } from "./rate-limit";
30	import { encryptSecret } from "./crypto-box";
31	import { DOMAIN_RE, generateStrongPassword } from "./ssh-exec";
32	import { appBySlug, APP_CATALOG, type AppRow } from "./cpanel-types";
33	import { appMode, type AppMode, type AppModeInfo } from "../worker/apps";
34	
35	/** What the panel needs to describe an app truthfully before it is installed. */
36	export type AppModeRow = AppModeInfo & { slug: string };
37	
38	type InstallResult =
39	  | {
40	      ok: true;
41	      id: string;
42	      domain: string;
43	      appName: string;
44	      mode: AppMode;
45	      /** Exactly the generated secrets that exist — nothing invented. */
46	      credentials: { label: string; value: string }[];
47	      /** What happens next, in plain language. */
48	      note: string;
49	    }
50	  | { ok: false; error: string };
51	type Result = { ok: true } | { ok: false; error: string };
52	
53	const EXCLUSIVE_JOBS = [
54	  "PROVISION",
55	  "REINSTALL",
56	  "DELETE",
57	  "RESIZE",
58	  "SUSPEND",
59	  "UNSUSPEND",
60	  "SNAPSHOT_ROLLBACK",
61	  "BACKUP_RESTORE",
62	  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
63	  // control-panel operations out of the way while the root filesystem is resized.
64	  "DISK_EXPAND",
65	] as const;
66	
67	async function ownedServer(serverId: string) {
68	  const user = await requireUser();
69	  const server = await db.server.findUnique({
70	    where: { id: serverId },
71	    select: { id: true, userId: true, status: true, hostname: true },
72	  });
73	  if (!server) throw new Error("Not found");
74	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
75	  return { user, server };
76	}
77	
78	async function ownedApp(id: string) {
79	  const user = await requireUser();
80	  const app = await db.appInstall.findUnique({ where: { id } });
81	  if (!app) throw new Error("Not found");
82	  if (app.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
83	  return { user, app };
84	}
85	
86	function throttle(userId: string, op: string, max: number): string | null {
87	  const rl = checkRateLimit(`cpanel:app:${op}:${userId}`, { max, windowMs: 60_000 });
88	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
89	}
90	
91	async function lifecycleBusy(serverId: string): Promise<boolean> {
92	  const n = await db.job.count({
93	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
94	  });
95	  return n > 0;
96	}
97	
98	function safeError(err: unknown): string {
99	  const msg = err instanceof Error ? err.message : String(err);
100	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
101	  return msg.slice(0, 300);
102	}
103	
104	function rowOut(a: {
105	  id: string;
106	  appSlug: string;
107	  domain: string;
108	  url: string | null;
109	  adminUser: string | null;
110	  status: string;
111	  error: string | null;
112	  createdAt: Date;
113	}): AppRow {
114	  return {
115	    id: a.id,
116	    appSlug: a.appSlug,
117	    domain: a.domain,
118	    url: a.url,
119	    adminUser: a.adminUser,
120	    status: a.status,
121	    error: a.error,
122	    createdAt: a.createdAt.toISOString(),
123	  };
124	}
125	
126	/** Derive a safe DB identifier (letters/digits/underscore, <=32) from a domain. */
127	function dbIdentFromDomain(domain: string, prefix: string): string {
128	  const base = domain.replace(/[^a-z0-9]/gi, "_").slice(0, 20);
129	  const suffix = Math.random().toString(36).slice(2, 6);
130	  return `${prefix}_${base}_${suffix}`.replace(/_+/g, "_").slice(0, 32);
131	}
132	
133	// ---------------------------------------------------------------------------
134	
135	/**
136	 * The catalogue's install modes, returned alongside the rows so the panel labels
137	 * every card with what this platform actually does. It travels with `listApps`
138	 * rather than as a shared constant because APP_MODES lives in worker/apps.ts
139	 * (server-only) and a "use server" module may export nothing but async
140	 * functions — the panel must not be able to render a promise we don't keep.
141	 */
142	function modeRows(): AppModeRow[] {
143	  return APP_CATALOG.map((a) => ({ slug: a.slug, ...appMode(a.slug) }));
144	}
145	
146	export async function listApps(
147	  serverId: string
148	): Promise<{ ok: true; apps: AppRow[]; modes: AppModeRow[] } | { ok: false; error: string }> {
149	  try {
150	    const { server } = await ownedServer(serverId);
151	    const rows = await db.appInstall.findMany({
152	      where: { serverId: server.id },
153	      orderBy: { createdAt: "desc" },
154	    });
155	    return { ok: true, apps: rows.map(rowOut), modes: modeRows() };
156	  } catch (err) {
157	    return { ok: false, error: safeError(err) };
158	  }
159	}
160	
161	export async function installApp(
162	  serverId: string,
163	  appSlug: string,
164	  domainInput: string,
165	  adminUserInput?: string
166	): Promise<InstallResult> {
167	  try {
168	    const { user, server } = await ownedServer(serverId);
169	    const limited = throttle(user.id, "install", 6);
170	    if (limited) return { ok: false, error: limited };
171	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to install an app." };
172	    if (await lifecycleBusy(server.id))
173	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
174	
175	    const app = appBySlug(appSlug);
176	    if (!app) return { ok: false, error: "Unknown application." };
177	
178	    // Apps we cannot install end to end are not sold as one-click installs; say
179	    // so up front instead of queueing a job that would have to lie or fail.
180	    const info = appMode(app.slug);
181	    if (info.mode === "unavailable") return { ok: false, error: `${app.name} — ${info.remaining}` };
182	
183	    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
184	    if (!DOMAIN_RE.test(domain))
185	      return { ok: false, error: "Enter a valid domain (e.g. blog.example.com) pointed at this server." };
186	
187	    // Domain must be free of an existing website on this server.
188	    const dupSite = await db.website.findFirst({ where: { serverId: server.id, domain } });
189	    if (dupSite) return { ok: false, error: `A website for ${domain} already exists on this server.` };
190	
191	    // An admin account only exists for apps whose install we complete ourselves.
192	    const managed = info.mode === "managed";
193	    const adminUser = managed
194	      ? (String(adminUserInput ?? "admin").replace(/[^a-z0-9_]/gi, "") || "admin").slice(0, 32)
195	      : null;
196	    const adminPassword = managed ? generateStrongPassword(18) : "";
197	    const dbName = app.engine ? dbIdentFromDomain(domain, "db") : "";
198	    const dbUser = app.engine ? dbIdentFromDomain(domain, "u") : "";
199	    const dbPassword = app.engine ? generateStrongPassword(20) : "";
200	
201	    // Create the primitives + the install record in one transaction.
202	    const { appRow } = await db.$transaction(async (tx) => {
203	      const website = await tx.website.create({
204	        data: {
205	          userId: user.id,
206	          serverId: server.id,
207	          domain,
208	          docRoot: `/var/www/${domain}`,
209	          phpVersion: app.php,
210	          isSubdomain: domain.split(".").length > 2,
211	          appSlug: app.slug,
212	          status: "PENDING",
213	        },
214	      });
215	      let database: { id: string } | null = null;
216	      if (app.engine) {
217	        database = await tx.vpsDatabase.create({
218	          data: {
219	            userId: user.id,
220	            serverId: server.id,
221	            engine: app.engine,
222	            name: dbName,
223	            dbUser,
224	            passwordEnc: encryptSecret(dbPassword),
225	            status: "PENDING",
226	          },
227	        });
228	      }
229	      const appRow = await tx.appInstall.create({
230	        data: {
231	          userId: user.id,
232	          serverId: server.id,
233	          appSlug: app.slug,
234	          domain,
235	          websiteId: website.id,
236	          databaseId: database?.id ?? null,
237	          adminUser,
238	          // Nothing is stored for an assisted app: the customer creates that
239	          // account inside the application's own wizard, so there is no
240	          // password for us to keep, apply — or claim.
241	          adminPassEnc: managed ? encryptSecret(adminPassword) : null,
242	          status: "PENDING",
243	        },
244	      });
245	      return { appRow };
246	    });
247	
248	    await db.job.create({ data: { type: "APP_INSTALL", serverId: server.id, payload: { appId: appRow.id } } });
249	    await db.auditLog.create({
250	      data: { userId: user.id, action: "cpanel.app.install", detail: `${app.slug} → ${domain} on ${server.hostname}` },
251	    });
252	    revalidatePath(`/dashboard/servers/${serverId}`);
253	
254	    // Credentials returned ONCE — and only the ones that actually exist.
255	    const credentials: { label: string; value: string }[] = [{ label: "URL", value: `http://${domain}/` }];
256	    if (managed && adminUser) {
257	      credentials.push({ label: "Admin user", value: adminUser });
258	      credentials.push({ label: "Admin password", value: adminPassword });
259	    }
260	    if (dbName) {
261	      credentials.push({ label: "Database", value: dbName });
262	      credentials.push({ label: "DB user", value: dbUser });
263	      credentials.push({ label: "DB password", value: dbPassword });
264	      credentials.push({ label: "DB host", value: "localhost" });
265	    }
266	    const note = managed
267	      ? `Installing now. ${app.name} is only marked installed once we have fetched the site from your server and ` +
268	        `checked that this admin password signs in — if that fails you will get a failure, not a green tick.`
269	      : `Installing now. This prepares the site, the database and ${app.name}'s files — it does NOT finish the ` +
270	        `install. ${info.remaining} Keep the database credentials above: the wizard asks for them.`;
271	
272	    return { ok: true, id: appRow.id, domain, appName: app.name, mode: info.mode, credentials, note };
273	  } catch (err) {
274	    return { ok: false, error: safeError(err) };
275	  }
276	}
277	
278	export async function removeApp(id: string): Promise<Result> {
279	  try {
280	    const { user, app } = await ownedApp(id);
281	    const limited = throttle(user.id, "remove", 10);
282	    if (limited) return { ok: false, error: limited };
283	    if (app.status === "INSTALLING") return { ok: false, error: "This app is still installing — try again shortly." };
284	
285	    // Tear down the provisioned site + database via their own worker jobs, then
286	    // drop the AppInstall record. The site/db rows carry the SSH cleanup.
287	    if (app.websiteId) {
288	      const site = await db.website.findUnique({ where: { id: app.websiteId } });
289	      if (site) {
290	        await db.website.update({ where: { id: site.id }, data: { status: "DELETING", appSlug: null } });
291	        await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: app.serverId, payload: { websiteId: site.id } } });
292	      }
293	    }
294	    if (app.databaseId) {
