168	  try {
169	    const { user, site } = await ownedWebsite(id);
170	    const limited = throttle(user.id, "dns", 12);
171	    if (limited) return { ok: false, error: limited };
172	
173	    const ip = await publicIpOf(site.serverId);
174	    if (!ip) {
175	      return {
176	        ok: false,
177	        error: "This server doesn't have a public IP yet — try again once it has finished provisioning.",
178	      };
179	    }
180	
181	    const res = await pointHostnameToIp({
182	      user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
183	      hostname: site.domain,
184	      ip,
185	    });
186	    if (!res.ok) return { ok: false, error: res.error };
187	
188	    await db.auditLog.create({
189	      data: {
190	        userId: user.id,
191	        action: "cpanel.website.dns",
192	        detail: `${site.domain} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
193	      },
194	    });
195	    revalidatePath(`/dashboard/servers/${site.serverId}`);
196	
197	    return {
198	      ok: true,
199	      message: res.simulated
200	        ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). No record was sent to Cloudflare.`
201	        : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). DNS changes can take a few minutes to reach everyone.`,
202	    };
203	  } catch (err) {
204	    return { ok: false, error: safeError(err) };
205	  }
206	}
