302	/**
303	 * Delete a site. A live site must be taken offline first — deleting the DB row
304	 * while the bundle is still served by nginx would orphan a live vhost.
305	 */
306	export async function deleteSite(id: string): Promise<Result> {
307	  try {
308	    const { user, site } = await ownedSite(id);
309	    const limited = throttle(user.id, "delete", 15);
310	    if (limited) return { ok: false, error: limited };
311	    if (site.status === "PUBLISHED" || site.status === "PUBLISHING") {
