8	/**
9	 * Customer SSL certificate management — one-click Let's Encrypt certs for a
10	 * domain the customer has already pointed at their server. Ordering is
11	 * ownership-checked here (at enqueue time); the actual issue runs in the worker
12	 * (worker/ssl.ts, SSL_ISSUE) which SSHes to the box and runs certbot — or, in
13	 * SANDBOX/staging, simulates a successful issue. worker/ssl.ts's `sslSweep` then
14	 * owns renewal and reconciliation.
15	 */
16	
17	// Basic FQDN: one or more dot-separated labels + a 2–24 char alpha TLD. Rejects
18	// wildcards, protocols, ports and paths — certbot wants a bare hostname.
19	const FQDN_RE =
20	  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
21	
22	/**
23	 * Let's Encrypt rate-limit guard. MUST stay in sync with worker/ssl.ts — this
24	 * module cannot import it (worker/ssl.ts pulls in ssh2, which must never reach
25	 * the Next bundle), so the four values are duplicated deliberately.
26	 *
27	 * LE allows 5 duplicate certificates (identical hostname set) per week; blowing
28	 * through it locks the customer out of HTTPS for a full week. Every source of
29	 * attempts — this file's manual request/renew and the worker's automatic renewal
30	 * sweep — shares one counter, so they cannot add up to more than the limit
31	 * between them.
32	 *
33	 * Two caps, because they stop different things: the LE cap stops the rate limit
34	 * being burned, and the total cap (which also counts attempts that never reached
35	 * LE, e.g. port 80 permanently occupied) stops a customer hammering a button that
36	 * cannot possibly succeed.
37	 */
38	const ISSUE_WINDOW_MS = 7 * 86400_000;
39	const MAX_LE_ATTEMPTS_PER_WINDOW = 4;
40	const MAX_TOTAL_ATTEMPTS_PER_WINDOW = 6;
41	/** Outcomes that never reached the ACME server, so never consumed a slot. */
42	const SSL_STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
43	const SSL_STEP_SANDBOX = "simulated (sandbox)";
44	
45	type SslPayload = { certId?: string; domain?: string; renewal?: boolean };
46	
47	function payloadOf(job: { payload: unknown }): SslPayload {
48	  return (job.payload ?? {}) as SslPayload;
49	}
