51	async function ownedServer(serverId: string) {
52	  const user = await requireUser();
53	  const server = await db.server.findUnique({ where: { id: serverId } });
54	  if (!server) throw new Error("Not found");
55	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
56	  return { user, server };
57	}
