59	async function ownedCertificate(id: string) {
60	  const user = await requireUser();
61	  const cert = await db.sslCertificate.findUnique({ where: { id } });
62	  if (!cert) throw new Error("Not found");
63	  if (cert.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
64	  return { user, cert };
65	}
