67	/**
68	 * Issue attempts against `domain` inside the current rate-limit window.
69	 *
70	 * Keyed on the hostname, not the certificate id: LE's duplicate-certificate
71	 * limit is per identical hostname set, and deleting a row and requesting it
72	 * again mints a fresh certId. A per-row counter would reset on every
73	 * delete/re-request, which is exactly how a customer chasing a broken
74	 * certificate could burn all five weekly slots in a couple of minutes.
75	 */
76	async function issueAttemptsFor(domain: string): Promise<{
77	  total: number;
78	  leRelevant: number;
79	  resumesAt: Date | null;
80	}> {
81	  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
82	  const jobs = await db.job.findMany({
83	    where: { type: "SSL_ISSUE", createdAt: { gt: since } },
84	    select: { payload: true, step: true, createdAt: true },
85	    orderBy: { createdAt: "asc" },
86	  });
87	  let total = 0;
88	  let leRelevant = 0;
89	  let oldest: Date | null = null;
90	  for (const j of jobs) {
91	    if (payloadOf(j).domain !== domain) continue;
92	    total++;
93	    // `step === null` means in flight (or a pre-2026-07-26 job): count it against
94	    // the limit. When in doubt we protect the limit, not the convenience.
95	    if (j.step !== SSL_STEP_PREFLIGHT_FAILED && j.step !== SSL_STEP_SANDBOX) leRelevant++;
96	    if (!oldest) oldest = j.createdAt;
97	  }
98	  return {
99	    total,
100	    leRelevant,
101	    resumesAt: oldest ? new Date(oldest.getTime() + ISSUE_WINDOW_MS) : null,
102	  };
103	}
104	
105	/** True when this hostname has used up its allowance for the current window. */
106	function rateLimited(rate: { total: number; leRelevant: number }): boolean {
107	  return (
108	    rate.leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW || rate.total >= MAX_TOTAL_ATTEMPTS_PER_WINDOW
109	  );
110	}
