112	function rateLimitMessage(
113	  domain: string,
114	  rate: { total: number; leRelevant: number; resumesAt: Date | null }
115	): string {
116	  const when = rate.resumesAt
117	    ? `${rate.resumesAt.toISOString().slice(0, 16).replace("T", " ")} UTC`
118	    : "later this week";
119	  if (rate.leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW) {
120	    return (
121	      `${rate.leRelevant} certificate requests for ${domain} have already reached Let's Encrypt in the ` +
122	      `last 7 days. Let's Encrypt allows only 5 identical certificates per week, and going over would ` +
123	      `block new certificates for this domain for a full week — so we stop one short. You can try again ` +
124	      `after ${when}.`
125	    );
126	  }
127	  return (
128	    `${rate.total} attempts for ${domain} have failed in the last 7 days before ever reaching Let's ` +
129	    `Encrypt, so another attempt would fail the same way. Fix the error shown on the certificate first; ` +
130	    `you can try again after ${when}.`
131	  );
132	}
