261	  const rate = await issueAttemptsFor(cert.domain);
262	  if (rateLimited(rate)) return { error: rateLimitMessage(cert.domain, rate) };
263	
264	  // One in-flight job per server, matching the worker's own invariant.
265	  const busy = await db.job.count({
266	    where: { serverId: cert.serverId, status: { in: ["QUEUED", "RUNNING"] } },
267	  });
268	  if (busy > 0) {
269	    return {
270	      error:
271	        "Another operation is already queued for this server. The platform runs one job at a time — try again once it finishes.",
272	    };
273	  }
274	
275	  await db.job.create({
276	    data: {
277	      type: "SSL_ISSUE",
278	      serverId: cert.serverId,
279	      // `renewal: true` keeps a still-valid certificate ACTIVE if the reissue
280	      // fails, instead of flipping a working site's row to FAILED.
281	      payload: { certId: cert.id, domain: cert.domain, renewal: true },
282	    },
283	  });
284	  await db.auditLog.create({
285	    data: { userId: user.id, action: "ssl.renew", detail: `${cert.domain}` },
286	  });
287	  revalidatePath("/dashboard/ssl");
288	  return {};
289	}
290	
291	/**
292	 * Permanently remove a certificate record (owner only).
293	 *
294	 * ISSUING is only protected while a job is genuinely running. Before
295	 * 2026-07-26 this refused every ISSUING row unconditionally, so a row stranded
296	 * by a worker restart was permanently undeletable — and because
297	 * requestCertificate rejects a new request while a PENDING/ISSUING/ACTIVE row
298	 * exists for the hostname, the customer lost the ability to get a certificate
299	 * for that domain at all, with no way to clear it themselves.
300	 */
301	export async function deleteCertificate(id: string): Promise<{ error?: string }> {
302	  let ctx;
303	  try {
304	    ctx = await ownedCertificate(id);
305	  } catch (e: any) {
306	    return { error: e.message };
307	  }
308	  const { user, cert } = ctx;
309	
310	  if (cert.status === "PENDING" || cert.status === "ISSUING") {
311	    const live = await liveIssueJob(cert.id);
312	    if (live?.status === "RUNNING") {
313	      return {
314	        error:
315	          "certbot is running for this domain right now — deleting mid-issue would leave a certificate on the " +
316	          "server with no record of it. Try again in a minute.",
317	      };
318	    }
319	    if (live) {
320	      // Queued but not started: cancel it, otherwise the worker would pick up a
321	      // job whose certificate row no longer exists and log a spurious failure.
322	      await db.job.updateMany({
323	        where: { id: live.id, status: "QUEUED" },
324	        data: {
325	          status: "FAILED",
326	          error: "Cancelled — the customer deleted the certificate request before it started.",
327	        },
328	      });
329	    }
330	  }
331	
332	  await db.sslCertificate.delete({ where: { id } });
333	  await db.auditLog.create({
334	    data: { userId: user.id, action: "ssl.delete", detail: `${cert.domain}` },
335	  });
336	  revalidatePath("/dashboard/ssl");
337	  return {};
338	}
339	
340	/**
341	 * Flip automatic renewal on/off for a certificate (owner only).
342	 *
343	 * This is no longer decoration: worker/ssl.ts's renewal sweep reads `autoRenew`
344	 * and, when it is off, reissues nothing and warns the customer before expiry
345	 * instead.
346	 */
347	export async function toggleAutoRenew(id: string): Promise<{ error?: string }> {
348	  let ctx;
349	  try {
350	    ctx = await ownedCertificate(id);
351	  } catch (e: any) {
352	    return { error: e.message };
353	  }
354	  await db.sslCertificate.update({
355	    where: { id },
356	    data: { autoRenew: !ctx.cert.autoRenew },
357	  });
358	  await db.auditLog.create({
359	    data: {
360	      userId: ctx.user.id,
361	      action: "ssl.autorenew",
362	      detail: `${ctx.cert.domain} -> ${!ctx.cert.autoRenew ? "on" : "off"}`,
363	    },
364	  });
365	  revalidatePath("/dashboard/ssl");
366	  return {};
367	}
