27	type Result = { ok: true } | { ok: false; error: string };
28	type CreateResult = { ok: true; id: string } | { ok: false; error: string };
29	
30	const EXCLUSIVE_JOBS = [
31	  "PROVISION",
32	  "REINSTALL",
33	  "DELETE",
34	  "RESIZE",
35	  "SUSPEND",
36	  "UNSUSPEND",
37	  "SNAPSHOT_ROLLBACK",
38	  "BACKUP_RESTORE",
39	  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
40	  // control-panel operations out of the way while the root filesystem is resized.
41	  "DISK_EXPAND",
42	] as const;
43	
44	/** Max length for a cron command line. */
45	const MAX_CMD_LEN = 500;
46	
47	async function ownedServer(serverId: string) {
48	  const user = await requireUser();
49	  const server = await db.server.findUnique({
50	    where: { id: serverId },
51	    select: {
52	      id: true,
53	      userId: true,
54	      status: true,
55	      hostname: true,
56	      rootPassword: true,
57	      rootPasswordEnc: true,
58	      sshPort: true,
59	      dedicatedIp: { select: { address: true } },
60	    },
61	  });
62	  if (!server) throw new Error("Not found");
63	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
64	  return { user, server };
65	}
66	
67	async function ownedCron(id: string) {
68	  const user = await requireUser();
69	  const cron = await db.cronJob.findUnique({ where: { id } });
70	  if (!cron) throw new Error("Not found");
71	  if (cron.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
72	  return { user, cron };
73	}
