149	export async function createCronJob(
150	  serverId: string,
151	  schedule: string,
152	  command: string,
153	  comment?: string
154	): Promise<CreateResult> {
155	  try {
156	    const { user, server } = await ownedServer(serverId);
157	    const limited = throttle(user.id, "create", 20);
158	    if (limited) return { ok: false, error: limited };
159	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to manage cron jobs." };
160	
161	    let normSchedule: string;
162	    let normCommand: string;
163	    try {
164	      normSchedule = assertCronSchedule(schedule);
165	      normCommand = validateCommand(command);
166	    } catch (e) {
167	      return { ok: false, error: e instanceof Error ? e.message : "Invalid cron entry." };
168	    }
169	    const note = comment ? String(comment).replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, 80) : null;
170	
171	    const count = await db.cronJob.count({ where: { serverId: server.id } });
172	    if (count >= 50) return { ok: false, error: "Cron job limit reached (50 per server)." };
173	
174	    const row = await db.cronJob.create({
175	      data: {
176	        userId: user.id,
177	        serverId: server.id,
178	        schedule: normSchedule,
179	        command: normCommand,
180	        comment: note,
181	        enabled: true,
182	        status: "PENDING",
183	      },
184	    });
185	    await db.job.create({ data: { type: "CRON_SYNC", serverId: server.id, payload: {} } });
186	    await db.auditLog.create({
187	      data: { userId: user.id, action: "cpanel.cron.create", detail: `${normSchedule} on ${server.hostname}` },
188	    });
189	    revalidatePath(`/dashboard/servers/${serverId}`);
