1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { validateRule } from "./firewall-rules";
7	import type { FirewallAction, FirewallProtocol } from "@prisma/client";
8	
9	/**
10	 * Inbound firewall (security-group) rules for a customer's VPS.
11	 *
12	 * Ownership is enforced exactly like the port-forward actions: `ownedServer`
13	 * throws unless the caller owns the server (or is an admin). Every mutable field
14	 * is validated + normalised by lib/firewall-rules.ts BEFORE it is persisted, and
15	 * again in the worker before it reaches a shell. Each change enqueues a
16	 * SYNC_FIREWALL job that re-applies the FULL rule set idempotently on the guest.
17	 */
18	
19	const MAX_RULES_PER_SERVER = 50;
20	
21	async function ownedServer(serverId: string) {
22	  const user = await requireUser();
23	  const server = await db.server.findUnique({ where: { id: serverId } });
24	  if (!server) throw new Error("Not found");
25	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
26	  return { user, server };
27	}
28	
29	async function enqueueSync(serverId: string) {
30	  await db.job.create({ data: { type: "SYNC_FIREWALL", serverId } });
31	}
32	
33	export async function listFirewallRules(serverId: string) {
34	  await ownedServer(serverId);
35	  return db.firewallRule.findMany({
36	    where: { serverId },
37	    orderBy: [{ position: "asc" }, { createdAt: "asc" }],
38	  });
39	}
40	
41	export async function addFirewallRule(prev: any, formData: FormData): Promise<{ error?: string }> {
42	  const serverId = String(formData.get("serverId") ?? "");
43	  const { user } = await ownedServer(serverId);
44	
45	  // VALIDATE everything before it is persisted. `validateRule` is the same gate
46	  // the worker uses, so a rule this action accepts is guaranteed buildable.
47	  const result = validateRule({
48	    action: formData.get("action"),
49	    protocol: formData.get("protocol"),
50	    portFrom: formData.get("portFrom"),
51	    portTo: formData.get("portTo"),
52	    sourceCidr: formData.get("sourceCidr"),
53	  });
54	  if (!result.ok) return { error: result.error };
55	
56	  // `comment` is customer free text — persisted + shown, NEVER shell-bound.
57	  const comment = String(formData.get("comment") ?? "").trim().slice(0, 200) || null;
58	
59	  const count = await db.firewallRule.count({ where: { serverId } });
60	  if (count >= MAX_RULES_PER_SERVER) {
61	    return { error: `Limit of ${MAX_RULES_PER_SERVER} firewall rules reached. Delete one first.` };
62	  }
63	
64	  const last = await db.firewallRule.findFirst({
65	    where: { serverId },
66	    orderBy: { position: "desc" },
67	    select: { position: true },
68	  });
69	  const position = (last?.position ?? -1) + 1;
70	
71	  const { action, protocol, portFrom, portTo, sourceCidr } = result.rule;
72	  await db.firewallRule.create({
73	    data: {
74	      serverId,
75	      direction: "INBOUND",
76	      action: action as FirewallAction,
77	      protocol: protocol as FirewallProtocol,
78	      portFrom,
79	      portTo,
80	      sourceCidr,
81	      comment,
82	      enabled: true,
83	      position,
84	    },
85	  });
86	
87	  await enqueueSync(serverId);
88	  await db.auditLog.create({
89	    data: {
90	      userId: user.id,
91	      action: "server.firewall_add",
92	      detail: `${serverId} ${action} ${protocol} ${portFrom ?? "*"}-${portTo ?? "*"} from ${sourceCidr}`,
93	    },
94	  });
95	  revalidatePath(`/dashboard/servers/${serverId}`);
96	  return {};
97	}
98	
99	export async function toggleFirewallRule(serverId: string, ruleId: string): Promise<{ error?: string }> {
100	  const { user } = await ownedServer(serverId);
101	  const rule = await db.firewallRule.findFirst({ where: { id: ruleId, serverId } });
102	  if (!rule) return { error: "Rule not found." };
103	  await db.firewallRule.update({ where: { id: rule.id }, data: { enabled: !rule.enabled } });
104	  await enqueueSync(serverId);
105	  await db.auditLog.create({
106	    data: { userId: user.id, action: "server.firewall_toggle", detail: `${serverId} ${ruleId} -> ${!rule.enabled}` },
107	  });
108	  revalidatePath(`/dashboard/servers/${serverId}`);
109	  return {};
110	}
111	
112	export async function deleteFirewallRule(serverId: string, ruleId: string): Promise<{ error?: string }> {
113	  const { user } = await ownedServer(serverId);
114	  await db.firewallRule.deleteMany({ where: { id: ruleId, serverId } });
115	  await enqueueSync(serverId);
116	  await db.auditLog.create({
117	    data: { userId: user.id, action: "server.firewall_delete", detail: `${serverId} ${ruleId}` },
118	  });
119	  revalidatePath(`/dashboard/servers/${serverId}`);
120	  return {};
121	}
