1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { familyFor } from "./game-config";
7	
8	/**
9	 * Mod-manager actions.
10	 *
11	 * Customers browse the per-game mod/plugin CATALOG (GameMod) and one-click
12	 * install/uninstall onto their server. Each change writes the desired state to a
13	 * `ServerMod` row (INSTALLING / REMOVING) and enqueues a single GAME_MOD_SYNC job
14	 * that reconciles the server to that state — the same state-driven pattern as
15	 * GAME_CONFIG (worker reads the DB, no per-op payloads to trust).
16	 *
17	 * Ownership + the "one in-flight job per server" invariant mirror
18	 * lib/actions-game-config.ts.
19	 */
20	
21	async function ownedServer(serverId: string) {
22	  const user = await requireUser();
23	  const server = await db.server.findUnique({
24	    where: { id: serverId },
25	    include: { osTemplate: true, gamePlan: true },
26	  });
27	  if (!server) throw new Error("Not found");
28	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
29	  return { user, server };
30	}
31	
32	async function hasInflightJob(serverId: string): Promise<boolean> {
33	  const pending = await db.job.count({
34	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
35	  });
36	  return pending > 0;
37	}
38	
39	export type CatalogMod = {
40	  id: string;
41	  name: string;
42	  slug: string;
43	  category: string;
44	  source: string;
45	  url: string | null;
46	  description: string | null;
47	  iconUrl: string | null;
48	  paid: boolean;
49	  featured: boolean;
50	  appliesToVariant: string | null;
51	  /** install state for THIS server: null = not installed. */
52	  status: string | null;
53	  error: string | null;
54	};
55	
56	export type ModsView = {
57	  family: string;
58	  variant: string | null;
59	  /** catalog entries (compatible with the server's variant), grouped by category. */
60	  categories: { category: string; mods: CatalogMod[] }[];
61	  installedCount: number;
62	  busy: boolean;
63	};
64	
65	/**
66	 * Load the mod catalog for an owned game server, annotated with each mod's
67	 * install state on this server. Only mods for the server's game family and
68	 * compatible with its selected variant are returned.
69	 */
70	export async function getServerMods(
71	  serverId: string
72	): Promise<{ error?: string; view?: ModsView }> {
73	  const { server } = await ownedServer(serverId);
74	  const family = familyFor(server);
75	  if (!family) return { error: "This server doesn't support mods." };
76	
77	  const variant = server.gameVariant ?? null;
78	
79	  const [catalog, installed, busy] = await Promise.all([
80	    db.gameMod.findMany({
81	      where: { gameFamily: family, active: true },
82	      orderBy: [{ featured: "desc" }, { popularity: "desc" }, { name: "asc" }],
83	    }),
84	    db.serverMod.findMany({ where: { serverId } }),
85	    hasInflightJob(serverId),
86	  ]);
87	
88	  const stateByMod = new Map(installed.map((m) => [m.modId, m]));
89	
90	  // Hide mods that target a different loader/variant than the server runs.
91	  const compatible = catalog.filter(
92	    (m) => !m.appliesToVariant || !variant || m.appliesToVariant === variant
93	  );
94	
95	  const byCategory = new Map<string, CatalogMod[]>();
96	  for (const m of compatible) {
97	    const st = stateByMod.get(m.id);
98	    const row: CatalogMod = {
99	      id: m.id,
100	      name: m.name,
101	      slug: m.slug,
102	      category: m.category,
103	      source: m.source,
104	      url: m.url,
105	      description: m.description,
106	      iconUrl: m.iconUrl,
107	      paid: m.paid,
108	      featured: m.featured,
109	      appliesToVariant: m.appliesToVariant,
110	      status: st?.status ?? null,
111	      error: st?.error ?? null,
112	    };
113	    const arr = byCategory.get(m.category) ?? [];
114	    arr.push(row);
115	    byCategory.set(m.category, arr);
116	  }
117	
118	  const categories = [...byCategory.entries()]
119	    .map(([category, mods]) => ({ category, mods }))
120	    .sort((a, b) => a.category.localeCompare(b.category));
121	
122	  const installedCount = installed.filter(
123	    (m) => m.status === "INSTALLED" || m.status === "INSTALLING"
124	  ).length;
125	
126	  return { view: { family, variant, categories, installedCount, busy } };
127	}
128	
129	/** Queue a mod for install on an owned server. */
130	export async function installMod(
131	  serverId: string,
132	  modId: string
133	): Promise<{ error?: string; ok?: boolean }> {
134	  const { user, server } = await ownedServer(serverId);
135	  const family = familyFor(server);
136	  if (!family) return { error: "This server doesn't support mods." };
137	
138	  const mod = await db.gameMod.findUnique({ where: { id: modId } });
139	  if (!mod || !mod.active) return { error: "That mod is unavailable." };
140	  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
141	  if (mod.appliesToVariant && server.gameVariant && mod.appliesToVariant !== server.gameVariant) {
142	    return { error: `${mod.name} needs the "${mod.appliesToVariant}" server type.` };
143	  }
144	
145	  const existing = await db.serverMod.findUnique({
146	    where: { serverId_modId: { serverId, modId } },
147	  });
148	  if (existing && (existing.status === "INSTALLED" || existing.status === "INSTALLING")) {
149	    return { error: `${mod.name} is already installed.` };
150	  }
151	
152	  if (await hasInflightJob(serverId)) {
153	    return { error: "Another operation is already in progress on this server." };
154	  }
155	
156	  await db.serverMod.upsert({
157	    where: { serverId_modId: { serverId, modId } },
158	    create: { serverId, modId, status: "INSTALLING", error: null },
159	    update: { status: "INSTALLING", error: null },
160	  });
161	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
162	  await db.auditLog.create({
163	    data: { userId: user.id, action: "gameserver.mod.install", detail: `${serverId} mod=${mod.slug}` },
164	  });
165	
166	  revalidatePath(`/dashboard/servers/${serverId}`);
167	  return { ok: true };
168	}
169	
170	/** Queue a mod for removal from an owned server. */
171	export async function uninstallMod(
172	  serverId: string,
173	  modId: string
174	): Promise<{ error?: string; ok?: boolean }> {
175	  const { user, server } = await ownedServer(serverId);
176	
177	  const existing = await db.serverMod.findUnique({
178	    where: { serverId_modId: { serverId, modId } },
179	    include: { mod: true },
180	  });
181	  if (!existing || existing.status === "REMOVED") {
182	    return { error: "That mod isn't installed." };
183	  }
184	
185	  if (await hasInflightJob(serverId)) {
186	    return { error: "Another operation is already in progress on this server." };
187	  }
188	
189	  await db.serverMod.update({
190	    where: { serverId_modId: { serverId, modId } },
191	    data: { status: "REMOVING", error: null },
192	  });
193	  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
194	  await db.auditLog.create({
195	    data: { userId: user.id, action: "gameserver.mod.uninstall", detail: `${serverId} mod=${existing.mod.slug}` },
196	  });
197	
198	  void server; // ownership already enforced above
199	  revalidatePath(`/dashboard/servers/${serverId}`);
200	  return { ok: true };
201	}
