1580	export async function createAddonDomain(accountId: string, domain: string): Promise<HostingResult> {
1581	  const ctx = await ownedSiteAccount(accountId);
1582	  if ("error" in ctx) return { error: ctx.error };
1583	  const { a } = ctx;
1584	  const name = normalizeHostingDomain(domain);
1585	  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
1586	  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
1587	  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
1588	  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
1589	  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
1590	  if (await isHostnameClaimed(name)) {
1591	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
1592	  }
1593	  const { docroot } = addonDomainPaths(a.username, name);
1594	  try {
1595	    await db.$transaction(async (tx) => {
1596	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1597	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
1598	      if (subs + addons >= a.maxSites) throw new Error("CAP");
1599	      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
1600	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) is the
1601	      // authoritative guard against another tenant committing this same
1602	      // server_name as their primary/subdomain/addon between our check and commit.
1603	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: a.id, kind: "ADDON" } });
1604	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
1605	    }, { isolationLevel: "Serializable" });
1606	  } catch (e) {
1607	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
1608	    if (isUniqueViolation(e)) return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
1609	    return { error: "That domain is already added, or the request raced — try again." };
1610	  }
1611	  revalidatePath(`/dashboard/hosting/${accountId}`);
1612	  return { ok: true };
1613	}
