1904	/** Normalize a comma-separated PHP-version list to distinct, valid `\d.\d` tokens. */
1905	function normalizePhpVersions(raw: string): string {
1906	  const seen = new Set<string>();
1907	  for (const tok of raw.split(",").map((s) => s.trim()).filter(Boolean)) {
1908	    if (/^\d\.\d$/.test(tok)) seen.add(tok);
1909	  }
1910	  return [...seen].join(",");
1911	}
