1927	  const maxDatabases = Math.round(Number(formData.get("maxDatabases") ?? 1));
1928	  const bandwidthTB = Number(formData.get("bandwidthTB") ?? 1);
1929	  const mailboxes = Math.round(Number(formData.get("mailboxes") ?? 1));
1930	  const tagline = String(formData.get("tagline") ?? "").trim();
1931	  const phpVersions = normalizePhpVersions(String(formData.get("phpVersions") ?? "8.3")) || "8.3";
1932	  const sortOrder = Math.round(Number(formData.get("sortOrder") ?? 0)) || 0;
1933	  const freeMigration = formData.get("freeMigration") === "on";
1934	  const featured = formData.get("featured") === "on";
1935	  const active = formData.get("active") === "on";
1936	
1937	  if (!/^[a-z][a-z0-9-]{1,31}$/.test(slug)) return { error: "Slug: lowercase letters, digits, dashes (2–32 chars)." };
1938	  if (!name) return { error: "Enter a plan name." };
1939	  if (priceCents < 0) return { error: "Price can’t be negative." };
